      "causa_raiz": "Alocação massiva de memória na Heap gerenciada (~5,4 MB no frame 1009), disparando o Garbage Collector de forma síncrona com pausa de 25.84ms. Somado ao tempo de CPU (23.60ms), o frame totalizou quase 50ms, violando o orçamento de 30.3ms (33 FPS) e causando um stutter grave.",
      "codigo_refatorado": "using System.Collections.Generic;
using UnityEngine;

public class OptimizedSpawner : MonoBehaviour
{
    [SerializeField] private GameObject prefab;
    [SerializeField] private int poolSize = 100;

    private readonly Queue<GameObject> poolQueue = new Queue<GameObject>();
    private static readonly Collider[] overlapResults = new Collider[50];

    private void Awake()
    {
        for (int i = 0; i < poolSize; i++)
        {
            GameObject obj = Instantiate(prefab);
            obj.SetActive(false);
            poolQueue.Enqueue(obj);
        }
    }

    public GameObject Spawn(Vector3 position, Quaternion rotation)
    {
        GameObject obj = (poolQueue.Count > 0) ? poolQueue.Dequeue() : Instantiate(prefab);
        obj.transform.position = position;
        obj.transform.rotation = rotation;
        obj.SetActive(true);
        return obj;
    }

    public void Despawn(GameObject obj)
    {
        obj.SetActive(false);
        poolQueue.Enqueue(obj);
    }

    public int CheckNonAlloc(Vector3 center, float radius, LayerMask mask)
    {
        return Physics.OverlapSphereNonAlloc(center, radius, overlapResults, mask);
    }
}",
      "explicacao_didatica": "Quando instanciamos objetos ou criamos novos arrays a cada frame (como em Physics.OverlapSphere ou strings), a memória temporária se acumula. Quando a Unity precisa limpar essa memória, ela pausa todo o jogo para o 'Garbage Collector' varrer o lixo, o que gerou a travada de 25ms. A solução é pré-alocar os objetos em um 'Pool' no início do jogo e reutilizá-los, além de usar métodos com 'NonAlloc' para reaproveitar o mesmo array repetidamente sem gerar lixo."
    }
  ],
